                    return game:HttpGet(inputValue)
                end)

                if ok and type(result) == "string" and #result > 0 then
                    isActive = pcall(value3, secondaryInput, result)
                end
            end

            if isActive then
                local ok, result = pcall(value, secondaryInput)
                if ok and result then
                    return result
                end
            end
        end

        return inputValue
    end

