                    if stateToken then
                        stateToken.Scale = floatingButtonsScale / 100
                    end
                end

                local animationProperties = { Scale = uiScaleValue / 100 }
                TweenService:Create(
                    mainGuiScale,
                    TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                    animationProperties
                ):Play()
            end

            local scrollingFrame = Instance.new("ScrollingFrame", primaryControl)
            scrollingFrame.Name = "LustContent"
            scrollingFrame.Size = UDim2.new(1, 0, 1, -48)
            scrollingFrame.Position = UDim2.new(0, 0, 0, 44)
            scrollingFrame.BackgroundTransparency = 1
            scrollingFrame.BorderSizePixel = 0
